// Parallel probe driver: replicates /tmp/probe/p.mjs isolation logic but runs cases concurrently.
import { execFile } from 'node:child_process';
const EXE = '/workspace/dataset/test19_executable';
const MK = { a: 'MKAA', b: 'MKBB', c: 'MKCC', d: 'MKDD', e: 'MKEE', f: 'MKFF' };
const ORDER = ['a', 'b', 'c', 'd', 'e', 'f'];

function runP(args) {
  const argv = [];
  for (const k of ORDER) argv.push('--' + k, args[k] === undefined ? MK[k] : args[k]);
  return new Promise((res) => {
    execFile(EXE, argv, { encoding: 'utf8', maxBuffer: 1 << 28 }, (err, stdout, stderr) => {
      if (err) res('ERR(' + err.code + ')\n' + (stdout || '') + (stderr || ''));
      else res(stdout);
    });
  });
}

function isolate(slot, out) {
  const lines = out.split('\n');
  const pos = ORDER.indexOf(slot);
  let start = 0;
  for (let k = 0; k < pos; k++) start = lines.indexOf('<p>' + MK[ORDER[k]] + '</p>', start) + 1;
  const end = pos < 5 ? lines.indexOf('<p>' + MK[ORDER[pos + 1]] + '</p>', start)
    : lines.indexOf('<h1>Combined Document</h1>', start);
  return lines.slice(start, end).join('\n');
}

function isolate5(out) {
  const lines = out.split('\n');
  let i = lines.length - 1;
  while (i >= 0 && lines[i] === '') i--;
  let j = i; while (j >= 0 && !lines[j].includes('</article>')) j--;
  const tail = lines.slice(j + 1, i + 1);
  const k = tail.lastIndexOf('<p>' + MK.e + '</p>');
  return tail.slice(k + 1).join('\n');
}

export async function phaseP(slot, s) {
  if (slot === '5') {
    const args = { ...MK }; args.f = s;
    return isolate5(await runP(args));
  }
  const args = { ...MK }; args[slot] = s;
  return isolate(slot, await runP(args));
}

// full raw output
export async function rawP(args) { return runP(args); }

export async function pool(tasks, conc = 8) {
  const results = new Array(tasks.length);
  let idx = 0;
  const workers = Array.from({ length: conc }, async () => {
    while (true) {
      const i = idx++;
      if (i >= tasks.length) return;
      results[i] = await tasks[i]();
    }
  });
  await Promise.all(workers);
  return results;
}

/** cases: array of [slot, text] or [slot, text, label] */
export async function runCases(cases, conc = 8) {
  const outs = await pool(cases.map(([slot, s]) => () => phaseP(slot, s)), conc);
  const lines = [];
  cases.forEach(([slot, s, label], i) => {
    lines.push('### ' + (label || '') + ' slot=' + slot);
    lines.push('IN=' + JSON.stringify(s));
    lines.push('OUT=' + JSON.stringify(outs[i]));
  });
  return lines.join('\n');
}

